package com.vaultorandroid
import androidx.test.ext.junit.runners.AndroidJUnit4
import androidx.test.platform.app.InstrumentationRegistry
import org.junit.*
import org.junit.Assert.*
import org.junit.runner.RunWith
import org.json.*
import java.io.File
import java.util.*
import java.security.MessageDigest
import java.util.zip.ZipFile
@RunWith(AndroidJUnit4::class)
class ExportStoreTest {
 init{require(android.os.Build.HARDWARE=="ranchu")}
 private val ctx get()=InstrumentationRegistry.getInstrumentation().targetContext
 private fun await(exports:VaultorExports,id:String):JSONObject{repeat(1000){val rows=exports.list();val row=(0 until rows.length()).map {rows.getJSONObject(it)}.single {it.getString("id")==id};if(row.getString("state") in listOf("ready","error"))return row;Thread.sleep(20)};error("Export timeout")}
 private fun withFixture(test:(CompanionStoreTest.Fixture,VaultorCompanions,VaultorExports)->Unit){val f=CompanionStoreTest().Fixture();val store=f.store();store.policy(JSONObject().put("metered",true).put("lowBattery",true).put("budgetMiB",128));assertEquals("ready",f.download(store).getString("status"));val exports=VaultorExports(f.context,store,{_,_,_->error("Offline export must never use the host")},{error("Offline export must never activate a source")},{emptyList()});try{test(f,store,exports)}finally{require(f.root.canonicalPath.startsWith(ctx.noBackupFilesDir.canonicalPath+"/r4-test-"));f.root.deleteRecursively()}}
 private fun input(f:CompanionStoreTest.Fixture,format:String="partial")=JSONObject().put("scope",f.scope).put("offline",true).put("label","Disposable downloaded fixture").put("request",JSONObject().put("scope","resources").put("ids",JSONArray(listOf(f.note,f.image))).put("depth",0).put("format",format))
 @Test fun offlinePartialRetainsOriginalBytesChecksumsAndExplicitCoverage()=withFixture {f,store,exports->val before=store.available(f.host,f.workspace)!!.getString("active");val id=exports.start(input(f)).getString("id");val row=await(exports,id);assertEquals(row.optString("detail"),"ready",row.getString("state"));val archive=File(f.root,"exports-v1/$id.bin");ZipFile(archive).use {zip->val manifest=JSONObject(zip.getInputStream(zip.getEntry("manifest.json")).bufferedReader().readText());assertEquals(6,manifest.getInt("version"));val workspace=JSONObject(zip.getInputStream(zip.getEntry("workspace.json")).bufferedReader().readText());assertEquals(2,workspace.getJSONArray("resources").length());assertEquals(0,workspace.getJSONArray("reviews").length());assertFalse(workspace.toString().contains(f.generation));val hashes=manifest.getJSONObject("checksums");for(name in hashes.keys()){val bytes=zip.getInputStream(zip.getEntry(name)).readBytes();assertEquals(hashes.getString(name),MessageDigest.getInstance("SHA-256").digest(bytes).joinToString(""){"%02x".format(it)})};assertArrayEquals(f.binary,zip.getInputStream(zip.getEntry("files/"+f.image)).readBytes());val coverage=JSONObject(zip.getInputStream(zip.getEntry("partial.json")).bufferedReader().readText());assertEquals("vaultor-partial",coverage.getString("kind"));assertTrue(coverage.getString("reviewCoverage").contains("acknowledged"));assertEquals(2,coverage.getJSONArray("inventory").length())};assertEquals(before,store.available(f.host,f.workspace)!!.getString("active"));assertArrayEquals(f.binary,store.file(f.scope,f.image)!!.readBytes());val destination=File(ctx.getExternalFilesDir(null),"r89-fixtures/offline-partial.zip");destination.parentFile!!.mkdirs();archive.copyTo(destination,true)}
 @Test fun markdownKeepsStructuredSidecarAndAvailableAssets()=withFixture {f,_,exports->val row=await(exports,exports.start(input(f,"markdown")).getString("id"));assertEquals(row.optString("detail"),"ready",row.getString("state"));ZipFile(File(f.root,"exports-v1/"+row.getString("id")+".bin")).use {zip->assertNotNull(zip.getEntry("notes/"+f.note+".md"));assertNotNull(zip.getEntry("notes/"+f.note+".json"));assertArrayEquals(f.binary,zip.getInputStream(zip.getEntry("files/"+f.image)).readBytes())};val link=JSONObject().put("type","resourceLink").put("attrs",JSONObject().put("resourceId",f.image).put("label","Original"));assertTrue(exports.markdown(link,types=mapOf(f.image to "file")).contains("../files/"+f.image));val code=JSONObject().put("type","codeBlock").put("content",JSONArray().put(JSONObject().put("type","text").put("text","a*b ``` original")));val md=exports.markdown(code);assertTrue(md.contains("a*b ``` original"));assertTrue(md.startsWith("````"))}
 @Test fun lockedAndCorruptSourcesCannotProduceReadyExports()=withFixture {f,store,exports->val job=store.available(f.host,f.workspace)!!.getString("active");val original=File(f.root,"companions-v1/$job/${f.note}.json");original.appendText("changed");val bad=await(exports,exports.start(input(f)).getString("id"));assertEquals("error",bad.getString("state"));assertFalse(File(f.root,"exports-v1/"+bad.getString("id")+".bin").exists());store.lock(f.scope);val locked=await(exports,exports.start(input(f)).getString("id"));assertEquals("error",locked.getString("state"));assertFalse(File(f.root,"exports-v1/"+locked.getString("id")+".bin").exists())}
 @Test fun offlineFullWorkspaceIsRejectedInsteadOfMislabelled()=withFixture {f,_,exports->val input=input(f).put("request",JSONObject().put("scope","workspace").put("ids",JSONArray()).put("depth",0).put("format","zip"));try{exports.start(input);fail("Offline full ZIP must be refused")}catch(_:IllegalArgumentException){}}
 @Test fun quotaFailureNeverEvictsTheDownloadedOriginal()=withFixture {f,store,exports->val occupied=File(f.root,"exports-v1/quota.part");java.io.RandomAccessFile(occupied,"rw").use {it.setLength(VaultorExports.MAX)};try{exports.start(input(f));fail("Export quota must refuse admission")}catch(_:IllegalArgumentException){};assertArrayEquals(f.binary,store.file(f.scope,f.image)!!.readBytes());assertEquals(0,exports.list().length())}
 @Test fun onlyAcknowledgedReviewEvidenceCanEnterPortableExports()=withFixture {f,store,_->
  fun capture(synced:Boolean):JSONObject {val body=JSONObject().put("resourceId",f.note).put("comment",if(synced)"Acknowledged evidence" else "UNSENT PRIVATE QUEUE").put("quote","").put("context","").put("locator",JSONObject().put("kind","resource"));return JSONObject().put("id",UUID.randomUUID().toString()).put("source",JSONObject().put("hostId",f.host).put("workspaceId",f.workspace).put("generation",f.generation).put("targetTitle","Target").put("targetType","note").put("address","https://private-not-portable")).put("body",body).put("delivery",JSONObject().put("state",if(synced)"synced" else "queued").put("receipt",JSONObject().put("author","Android").put("createdAt","2026-10-22T00:00:00Z").put("updatedAt","2026-10-22T00:00:00Z").put("status","open")))}
  val evidence=listOf(capture(true),capture(false));val exports=VaultorExports(f.context,store,{_,_,_->error("No offline host requests")},{},{evidence});val row=await(exports,exports.start(input(f)).getString("id"));assertEquals(row.optString("detail"),"ready",row.getString("state"));ZipFile(File(f.root,"exports-v1/"+row.getString("id")+".bin")).use {zip->val workspace=JSONObject(zip.getInputStream(zip.getEntry("workspace.json")).bufferedReader().readText());assertEquals(1,workspace.getJSONArray("reviews").length());assertEquals("Acknowledged evidence",workspace.getJSONArray("reviews").getJSONObject(0).getString("comment"));assertFalse(workspace.toString().contains("UNSENT PRIVATE QUEUE"));assertFalse(workspace.toString().contains("private-not-portable"))}
 }

}
